	public override void ExportTo(StiReport report, Stream stream, StiExportSettings settings)
	{
		ExportPowerPoint(report, stream, settings as StiPpt2007ExportSettings);
		InvokeExporting(100, 100, 1, 1);
	}

	public override void Export(StiReport report, string fileName, bool sendEMail, StiGuiMode guiMode)
	{
		//IL_0005: Unknown result type (might be due to invalid IL or missing references)
		//IL_0065: Unknown result type (might be due to invalid IL or missing references)
		//IL_0067: Unknown result type (might be due to invalid IL or missing references)
		//IL_0074: Unknown result type (might be due to invalid IL or missing references)
		//IL_007e: Expected O, but got Unknown
		IStiFormRunner exportFormRunner = StiGuiOptions.GetExportFormRunner("StiXpsExportSetupForm", guiMode, base.OwnerWindow);
		try
		{
			exportFormRunner["CurrentPage"] = report.CurrentPrintPage;
			exportFormRunner["OpenAfterExportEnabled"] = !sendEMail;
			exportFormRunner["ExportFormat"] = StiExportFormat.Ppt2007;
			this.report = report;
			this.fileName = fileName;
			this.sendEMail = sendEMail;
			this.guiMode = guiMode;
			exportFormRunner.Complete += new StiShowDialogCompleteEventHandler(Form_Complete);
			exportFormRunner.ShowDialog();
		}
		finally
		{
			((IDisposable)exportFormRunner)?.Dispose();
		}
	}

	public override string GetFilter()
	{
		return StiLocalization.Get("FileFilters", "Ppt2007Files");
	}

	private void Form_Complete(IStiFormRunner form, StiShowDialogCompleteEvetArgs e)
	{
		//IL_0056: Unknown result type (might be due to invalid IL or missing references)
		//IL_00d0: Unknown result type (might be due to invalid IL or missing references)
		if (e.DialogResult)
		{
			if (string.IsNullOrEmpty(fileName))
			{
				fileName = GetFileName(report, sendEMail);
			}
			if (fileName == null)
			{
				return;
			}
			StiFileUtils.ProcessReadOnly(fileName);
			try
			{
				using FileStream stream = new FileStream(fileName, FileMode.Create);
				StartProgress(guiMode);
				StiPpt2007ExportSettings stiPpt2007ExportSettings = new StiPpt2007ExportSettings();
				stiPpt2007ExportSettings.PageRange = form["PagesRange"] as StiPagesRange;
				stiPpt2007ExportSettings.ImageResolution = (float)form["Resolution"];
				stiPpt2007ExportSettings.ImageQuality = (float)form["ImageQuality"];
				StiPpt2007ExportSettings settings = stiPpt2007ExportSettings;
				StartExport(report, stream, settings, sendEMail, (bool)form["OpenAfterExport"], fileName, guiMode);
				return;
			}
			catch (Exception ex)
			{
				throw ex;
			}
		}
		base.IsStopped = true;
	}

	private string GetLineStyle(StiPenStyle penStyle)
	{
		//IL_0000: Unknown result type (might be due to invalid IL or missing references)
		//IL_001e: Expected I4, but got Unknown
		return (int)penStyle switch
		{
			0 => "solid", 
			4 => "sysDot", 
			1 => "sysDash", 
			2 => "sysDashDot", 
			3 => "sysDashDotDot", 
			5 => "solid", 
			_ => "solid", 
		};
	}

	private string StringToUrl(string input)
	{
		UTF8Encoding uTF8Encoding = new UTF8Encoding();
		byte[] bytes = uTF8Encoding.GetBytes(input);
		StringBuilder stringBuilder = new StringBuilder();
		byte[] array = bytes;
		foreach (byte b in array)
		{
			if (b < 32 || b > 127 || wrongUrlSymbols.IndexOf((char)b) != -1)
			{
				stringBuilder.Append($"%{b:x2}");
			}
			else
			{
				stringBuilder.Append((char)b);
			}
		}
		return stringBuilder.ToString();
	}

	private int Convert(double x)
	{
		return (int)Math.Round((decimal)(x * HiToTwips));
	}

	private int ConvertTwipsToEmu(double x)
	{
		return (int)Math.Round((decimal)(x / HiToTwips / 100.0 * 914400.0));
	}

	private int ConvertToEmu(double x)
	{
		return (int)Math.Round((decimal)(x / 100.0 * 914400.0));
	}

	private void WriteColor(XmlWriter writer, Color color)
	{
		writer.WriteStartElement("a:srgbClr");
		writer.WriteAttributeString("val", $"{color.ToArgb() & 0xFFFFFF:X6}");
		if (color.A != byte.MaxValue)
		{
			int num = (int)((float)(int)color.A / 256f * 100000f);
			writer.WriteStartElement("a:alpha");
			writer.WriteAttributeString("val", $"{num}");
			writer.WriteEndElement();
		}
		writer.WriteEndElement();
	}

