	private void WriteExceedMargins(XmlWriter writer, StiText text)
	{
		//IL_0040: Unknown result type (might be due to invalid IL or missing references)
		//IL_0045: Unknown result type (might be due to invalid IL or missing references)
		if (text == null || text.ExceedMargins == StiExceedMargins.None || text.Brush is StiEmptyBrush)
		{
			return;
		}
		Color color = StiBrush.ToColor(text.Brush);
		if (!color.Equals((object?)Color.Transparent))
		{
			RectangleD clientRectangle = text.ClientRectangle;
			if ((text.ExceedMargins & StiExceedMargins.Left) > StiExceedMargins.None)
			{
				((RectangleD)(ref clientRectangle)).Width = ((RectangleD)(ref clientRectangle)).Width + (((RectangleD)(ref clientRectangle)).Left + text.Page.Margins.Left);
				((RectangleD)(ref clientRectangle)).X = 0.0 - text.Page.Margins.Left;
			}
			if ((text.ExceedMargins & StiExceedMargins.Top) > StiExceedMargins.None)
			{
				((RectangleD)(ref clientRectangle)).Height = ((RectangleD)(ref clientRectangle)).Height + (((RectangleD)(ref clientRectangle)).Top + text.Page.Margins.Top);
				((RectangleD)(ref clientRectangle)).Y = 0.0 - text.Page.Margins.Top;
			}
