			{
				((RectangleD)(ref clientRectangle)).Width = ((RectangleD)(ref clientRectangle)).Width + (text.Page.Width + text.Page.Margins.Right - ((RectangleD)(ref clientRectangle)).Right);
			}
			if ((text.ExceedMargins & StiExceedMargins.Bottom) > StiExceedMargins.None)
			{
				((RectangleD)(ref clientRectangle)).Height = ((RectangleD)(ref clientRectangle)).Height + (text.Page.Height + text.Page.Margins.Bottom - ((RectangleD)(ref clientRectangle)).Bottom);
			}
			writer.WriteStartElement("p:sp");
			writer.WriteStartElement("p:nvSpPr");
			writer.WriteStartElement("p:cNvPr");
			writer.WriteAttributeString("id", $"{idCounter}");
			writer.WriteAttributeString("name", $"Rectangle {idCounter}");
			writer.WriteEndElement();
			writer.WriteStartElement("p:cNvSpPr");
			writer.WriteEndElement();
			writer.WriteStartElement("p:nvPr");
			writer.WriteEndElement();
