	private void WriteStiImage(XmlWriter writer, StiComponent comp)
	{
		bool flag = false;
		if (comp is IStiExportImage stiExportImage)
		{
			IStiExportImageExtended stiExportImageExtended = stiExportImage as IStiExportImageExtended;
			float zoom = imageResolution;
			Image val = null;
			if (comp.IsExportAsImage(StiExportFormat.Ppt2007))
			{
				try
				{
					Thread.CurrentThread.CurrentCulture = currentCulture;
					val = ((stiExportImageExtended == null || !stiExportImageExtended.IsExportAsImage(StiExportFormat.Ppt2007)) ? stiExportImage.GetImage(ref zoom) : stiExportImageExtended.GetImage(ref zoom, StiExportFormat.ImagePng));
				}
				finally
				{
					Thread.CurrentThread.CurrentCulture = newCulture;
				}
			}
			if (val != null)
			{
				int num = imageCache.AddImageInt(val);
				val.Dispose();
				writer.WriteStartElement("p:pic");
				writer.WriteStartElement("p:nvPicPr");
				writer.WriteStartElement("p:cNvPr");
				writer.WriteAttributeString("id", $"{idCounter}");
				writer.WriteAttributeString("name", $"Picture {idCounter + 1}");
				writer.WriteAttributeString("descr", $"Picture {idCounter + 1} description");
				WriteHyperlinkInfo(writer, comp);
				writer.WriteEndElement();
				writer.WriteStartElement("p:cNvPicPr");
				writer.WriteStartElement("a:picLocks");
				writer.WriteAttributeString("noChangeAspect", "1");
				writer.WriteEndElement();
				writer.WriteFullEndElement();
				writer.WriteStartElement("p:nvPr");
				writer.WriteEndElement();
				writer.WriteFullEndElement();
				writer.WriteStartElement("p:blipFill");
				writer.WriteStartElement("a:blip");
				writer.WriteAttributeString("r:embed", $"rId{1 + imageCache.ImageIndex.Count - imageListOffset}");
				writer.WriteEndElement();
				writer.WriteStartElement("a:stretch");
				writer.WriteStartElement("a:fillRect");
				writer.WriteEndElement();
				writer.WriteFullEndElement();
				writer.WriteFullEndElement();
				flag = WriteSpPr(writer, comp);
				writer.WriteFullEndElement();
			}
		}
		if (flag || comp is StiLinePrimitive)
		{
			WriteBorder(writer, comp);
		}
	}

