			stiImage.Width = page.PageWidth;
			stiImage.Height = page.PageHeight;
			if (page.Watermark.ImageStretch)
			{
				stiImage.Stretch = true;
			}
			stiImage.VertAlignment = (StiVertAlignment)1;
			stiImage.HorAlignment = (StiHorAlignment)2;
			WriteStiImage(writer, stiImage);
		}
	}

	private void WriteHyperlinkInfo(XmlWriter writer, StiComponent comp)
	{
		if (comp.HyperlinkValue == null)
		{
			return;
		}
		string text = comp.HyperlinkValue.ToString().Trim();
		if (text.Length > 0 && !text.StartsWith("javascript:") && !text.StartsWith("#", StringComparison.InvariantCulture))
		{
			string value = StringToUrl(text);
			int num = hyperlinkList.IndexOf(value);
			if (num == -1)
			{
				hyperlinkList.Add(value);
				num = hyperlinkList.Count;
			}
			writer.WriteStartElement("a:hlinkClick");
			writer.WriteAttributeString("r:id", $"hId{num}");
			writer.WriteEndElement();
		}
	}

	private MemoryStream WriteImage(int number)
	{
		MemoryStream memoryStream = new MemoryStream();
		byte[] array = (byte[])imageCache.ImagePackedStore[number];
		memoryStream.Write(array, 0, array.Length);
		return memoryStream;
	}

	public void ExportPowerPoint(StiReport report, string fileName)
	{
		FileStream fileStream = null;
		try
		{
			StiFileUtils.ProcessReadOnly(fileName);
			fileStream = new FileStream(fileName, FileMode.Create);
			ExportPowerPoint(report, fileStream);
		}
		finally
		{
			fileStream.Flush();
			fileStream.Close();
		}
	}

	public void ExportPowerPoint(StiReport report, Stream stream)
	{
		ExportPowerPoint(report, stream, new StiPpt2007ExportSettings());
	}

	public void ExportPowerPoint(StiReport report, Stream stream, StiPagesRange pageRange)
	{
		StiPpt2007ExportSettings settings = new StiPpt2007ExportSettings
		{
			PageRange = pageRange
		};
		ExportPowerPoint(report, stream, settings);
	}

	public void ExportPowerPoint(StiReport report, Stream stream, StiPpt2007ExportSettings settings)
	{
		//IL_0113: Unknown result type (might be due to invalid IL or missing references)
		//IL_0119: Expected O, but got Unknown
		StiLogService.Write(((object)this).GetType(), "Export report to PowerPoint 2007 format");
		if (settings == null)
		{
			throw new ArgumentNullException("The 'settings' argument cannot be equal in null.");
		}
		StiPagesRange pageRange = settings.PageRange;
		imageResolution = settings.ImageResolution;
		imageQuality = settings.ImageQuality;
		xmlIndentation = -1;
		if (imageResolution < 10f)
		{
			imageResolution = 10f;
		}
		imageResolution /= 100f;
		currentCulture = Thread.CurrentThread.CurrentCulture;
		newCulture = new CultureInfo("en-US", useUserOverride: false);
		try
		{
			Thread.CurrentThread.CurrentCulture = newCulture;
			reportCulture = ((!string.IsNullOrWhiteSpace(report.Culture)) ? report.Culture : null);
			StiPagesCollection selectedPages = pageRange.GetSelectedPages(report.RenderedPages);
			if (base.IsStopped)
			{
				return;
			}
			base.StatusString = StiLocalization.Get("Export", "ExportingCreatingDocument");
			imageCache = new StiImageCache(StiOptions.Export.PowerPoint.AllowImageComparer, StiOptions.Export.PowerPoint.StoreImagesAsPng ? ImageFormat.Png : ImageFormat.Jpeg, imageQuality);
			StiZipWriter20 val = new StiZipWriter20();
			val.Begin(stream, true);
			val.AddFile("[Content_Types].xml", WriteContentTypes(selectedPages.Count));
			val.AddFile("_rels/.rels", WriteMainRels());
			val.AddFile("docProps/app.xml", WriteDocPropsApp(selectedPages.Count));
			val.AddFile("docProps/core.xml", WriteDocPropsCore());
			val.AddFile("ppt/tableStyles.xml", WriteTableStyles());
			val.AddFile("ppt/presProps.xml", WritePresProps());
			val.AddFile("ppt/viewProps.xml", WriteViewProps());
			val.AddFile("ppt/theme/theme1.xml", WriteTheme());
			val.AddFile("ppt/slideMasters/slideMaster1.xml", WriteSlideMaster());
			val.AddFile("ppt/slideMasters/_rels/slideMaster1.xml.rels", WriteSlideMasterRels());
			for (int i = 0; i < 11; i++)
			{
				val.AddFile($"ppt/slideLayouts/slideLayout{i + 1}.xml", WriteSlideLayout(i + 1, selectedPages[0]));
				val.AddFile($"ppt/slideLayouts/_rels/slideLayout{i + 1}.xml.rels", WriteSlideLayoutRels());
			}
			val.AddFile("ppt/presentation.xml", WritePresentation(selectedPages));
			val.AddFile("ppt/_rels/presentation.xml.rels", WritePresentationRels(selectedPages));
			imageListOffset = 0;
			hyperlinkList = new ArrayList();
			for (int j = 0; j < selectedPages.Count; j++)
			{
				InvokeExporting(j, selectedPages.Count, 0, 1);
				if (base.IsStopped)
				{
					return;
				}
				StiPage page = selectedPages[j];
				selectedPages.GetPage(page);
				val.AddFile($"ppt/slides/slide{j + 1}.xml", WriteSlide(j, selectedPages));
				val.AddFile($"ppt/slides/_rels/slide{j + 1}.xml.rels", WriteSlideRels(j));
				imageListOffset = imageCache.ImageIndex.Count;
				hyperlinkList.Clear();
			}
			if (imageCache.ImagePackedStore.Count > 0)
			{
				for (int k = 0; k < imageCache.ImagePackedStore.Count; k++)
				{
					val.AddFile(string.Format("ppt/media/image{0:D5}.{1}", k + 1, StiOptions.Export.PowerPoint.StoreImagesAsPng ? "png" : "jpeg"), WriteImage(k));
				}
			}
			val.End();
		}
		finally
		{
			StiExportUtils.EnableFontSmoothing(report);
			Thread.CurrentThread.CurrentCulture = currentCulture;
			imageCache.Clear();
			hyperlinkList = null;
		}
	}
}
